import { createPublicClient, createWalletClient, http, type Account, type Chain, type Transport } from 'viem';
import { privateKeyToAccount } from 'viem/accounts';
import { createViemClient, createViemSdk } from '@matterlabs/zksync-js/viem'; const L1_RPC = 'http://localhost:8545'; // e.g. https://sepolia.infura.io/v3/XXX
const GW_RPC = 'http://localhost:3052'; // gateway chain RPC
const SRC_L2_RPC = 'http://localhost:3050'; // source L2 RPC
const DST_L2_RPC = 'http://localhost:3051'; // destination L2 RPC
const PRIVATE_KEY = process.env.PRIVATE_KEY || '';
const TOKEN_SRC_ADDRESS = process.env.TOKEN_SRC_ADDRESS || ''; // ERC-20 token on source L2 async function main() { if (!PRIVATE_KEY) throw new Error('Set PRIVATE_KEY in env'); const account = privateKeyToAccount(PRIVATE_KEY as `0x${string}`); const me = account.address as `0x${string}`; const l1 = createPublicClient({ transport: http(L1_RPC) }); const l2Src = createPublicClient({ transport: http(SRC_L2_RPC) }); const l2Dst = createPublicClient({ transport: http(DST_L2_RPC) }); const l1Wallet = createWalletClient<Transport, Chain, Account>({ account, transport: http(L1_RPC), }); const client = createViemClient({ l1, l2: l2Src, l1Wallet }); const sdk = createViemSdk(client, { interop: { gwChain: GW_RPC }, }); const params = { actions: [ { type: 'sendErc20' as const, token: TOKEN_SRC_ADDRESS as `0x${string}`, to: me, amount: 1_000_000n, }, ], }; const quote = await sdk.interop.quote(l2Dst, params); // { // route: 'direct' | 'indirect', // approvalsNeeded: [{ token, spender, amount }], // ERC-20 approval needed // totalActionValue: 0n, // bridgedTokenTotal: 1_000_000n, // interopFee: { token: '0x000...', amount: bigint }, // l2Fee?: bigint // } void quote; const plan = await sdk.interop.prepare(l2Dst, params); // { // route: 'direct' | 'indirect', // summary: InteropQuote, // steps: [{ key, kind, description, tx }] // } void plan; // Send the interop bundle on source L2 const handle = await sdk.interop.create(l2Dst, params); // { // kind: 'interop', // l2SrcTxHash: Hex, // stepHashes: Record<string, Hex>, // plan: InteropPlan // } const st = await sdk.interop.status(l2Dst, handle); // st.phase: 'SENT' | 'VERIFIED' | 'EXECUTED' | 'UNBUNDLED' | 'FAILED' | 'UNKNOWN' void st; // Wait until the bundle proof is available on destination const finalizationInfo = await sdk.interop.wait(l2Dst, handle, { pollMs: 5_000, timeoutMs: 30 * 60_000, }); // Returns InteropFinalizationInfo once bundle proof is available on destination // Execute the bundle on destination L2 const result = await sdk.interop.finalize(l2Dst, finalizationInfo); // { bundleHash: Hex, dstExecTxHash: Hex } console.log('Executed on destination:', result.dstExecTxHash);
} main().catch((e) => { console.error(e); process.exit(1);
}); create() sends the interop bundle on source L2 . wait() blocks until the bundle proof is available on destination. finalize() executes the bundle on destination L2 .

