type WithdrawalKey = { chainIdL2: bigint; l2BatchNumber: bigint; l2MessageIndex: bigint;
}; type WithdrawalPhase = | 'L2_PENDING' // tx not in an L2 block yet | 'L2_INCLUDED' // we have the L2 receipt | 'PENDING' // inclusion known; proof data not yet derivable/available | 'READY_TO_FINALIZE' // Ready to call finalize on L1 | 'FINALIZING' // L1 tx sent but not picked up yet | 'FINALIZED' // L2-L1 tx finalized on L1 | 'FINALIZE_FAILED' // prior L1 finalize reverted | 'UNFINALIZABLE' // finalization can never succeed for this withdrawal | 'UNKNOWN'; // Withdrawal Status
type WithdrawalStatus = { phase: WithdrawalPhase; l2TxHash: Hex; l1FinalizeTxHash?: Hex; key?: WithdrawalKey; // Why the withdrawal is PENDING or UNFINALIZABLE, when known. reason?: string;
}; interface FinalizeDepositParams { chainId: bigint; l2BatchNumber: bigint; l2MessageIndex: bigint; l2Sender: Address; l2TxNumberInBatch: number; message: Hex; merkleProof: Hex[];
} // Protocol v32+ finalization inputs: the withdrawal's interop bundle and its inclusion proof.
interface WithdrawalBundleFinalization { bundle: Hex; bundleHash: Hex; proof: { chainId: bigint; l1BatchNumber: bigint; l2MessageIndex: bigint; message: { txNumberInBatch: number; sender: Address; data: Hex }; proof: Hex[]; };
} // Outcome of a withdrawal bundle on the destination.
// - `finalized` — the call ran; funds released on L1
// - `failed` — terminally unwound with the call cancelled; funds NOT released
// - `pending` — not resolved yet
type WithdrawalOutcome = 'finalized' | 'failed' | 'pending'; // Which contract finalizes the withdrawal, and with which arguments.
// - `legacy-withdrawal` → L1Nullifier.finalizeDeposit (protocol v31 and below)
// - `interop-bundle` → L1InteropHandler.executeBundle (protocol v32 and above)
type WithdrawalFinalization = | { protocol: 'legacy-withdrawal'; params: FinalizeDepositParams } | { protocol: 'interop-bundle'; params: WithdrawalBundleFinalization }; interface ResolvedWithdrawalFinalization { target: Address; finalization: WithdrawalFinalization; key: WithdrawalKey;
} // Finalization readiness states
// Used for `status()`
type FinalizeReadiness = | { kind: 'READY' } | { kind: 'FINALIZED' } | { kind: 'NOT_READY'; // temporary, retry later reason: 'paused' | 'batch-not-executed' | 'root-missing' | 'unknown'; detail?: string; } | { kind: 'UNFINALIZABLE'; // permanent, won’t become ready reason: 'message-invalid' | 'invalid-chain' | 'settlement-layer' | 'unsupported'; detail?: string; }; interface FinalizationEstimate { gasLimit: bigint; maxFeePerGas: bigint; maxPriorityFeePerGas: bigint;
} interface FinalizationServices { /** * Derive the finalization arguments for a withdrawal, tagged with the protocol they belong to. */ fetchFinalization(l2TxHash: Hex): Promise<ResolvedWithdrawalFinalization>; /** * Build `finalizeDeposit` params. * * @deprecated Only meaningful on protocol v31 chains. Throws on v32+, where withdrawals are * finalized through the interop handler — use {@link fetchFinalization} instead. */ fetchFinalizeDepositParams( l2TxHash: Hex, ): Promise<{ params: FinalizeDepositParams; nullifier: Address }>; /** Check whether the withdrawal has already been finalized on L1. */ isWithdrawalFinalized(finalization: WithdrawalFinalization): Promise<boolean>; /** * Classify the withdrawal's on-chain outcome. Distinguishes a terminally-failed bundle (unwound * with its call cancelled) from one that is merely not finalized yet. */ withdrawalOutcome(finalization: WithdrawalFinalization): Promise<WithdrawalOutcome>; /** Simulate finalization on L1 to check readiness. */ simulateFinalizeReadiness(finalization: WithdrawalFinalization): Promise<FinalizeReadiness>; /** Estimate gas & fees for finalization on L1. */ estimateFinalization(finalization: WithdrawalFinalization): Promise<FinalizationEstimate>; /** Send the finalization transaction on L1. */ finalize( finalization: WithdrawalFinalization, ): Promise<{ hash: string; wait: () => Promise<TransactionReceipt> }>;
}

